parameters.jsCode:
const sceneRows = $('Load Project').item.json.rows;
const bibles = $('Load Project (Bibles)').item.json.rows;
const projectId = sceneRows[0].project_id;

const scenes = sceneRows.map(row => ({
  id: row.scene_id,
  scene_number: row.scene_number,
  chapter_number: row.chapter_number,
  title: row.scene_title,
  summary: row.summary,
  characters_present: JSON.parse(row.characters_present || '[]'),
  location: row.location,
  time_period: row.time_period,
  emotional_tone: row.emotional_tone,
  word_count: row.word_count || 0
}));

const biblesMap = {};
for (const b of bibles) {
  biblesMap[b.bible_type] = b.content;
}

// Batch scenes for LLM processing (groups of 10)
const batchSize = 10;
const batches = [];
for (let i = 0; i < scenes.length; i += batchSize) {
  batches.push(scenes.slice(i, i + batchSize));
}

return [{
  json: {
    project_id: projectId,
    title: sceneRows[0].title,
    language: sceneRows[0].language,
    scenes: scenes,
    bibles: biblesMap,
    total_scenes: scenes.length,
    batches: batches,
    total_batches: batches.length
  }
}];

parameters.jsonBody:
={
  "model": "{{ $env.OLLAMA_MODEL || 'llama3' }}",
  "prompt": "Generate production metadata for each scene in this batch from '{{ $('Execute Logic').item.json.title }}'.

Scenes: {{ JSON.stringify($('Execute Logic').item.json.batches[0]) }}

For each scene, generate:
1. scene_type: {dialogue, action, exposition, montage, transition}
2. cinematography: {shot_types (array), camera_movement, lighting_mood, color_palette}
3. audio: {music_mood, sound_effects, ambient_sounds}
4. dialogue_heavy: boolean
5. fight_scene: boolean
6. fight_details: {type, intensity, choreography_notes} if fight_scene is true
7. emotional_beats: array of {moment, intensity (1-10), description}
8. duration_estimate: seconds based on word_count and scene_type
9. production_complexity: low/medium/high
10. location_requirements: specific needs for the location

Return as JSON array, one entry per scene with scene_id as key.",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const responseText = $input.first().json.response || '{}';
let planningData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    planningData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      planningData = Object.entries(parsed).map(([key, val]) => ({ scene_id: key, ...val }));
    }
  }
} catch (e) {
  planningData = [];
}

const scenes = $('Execute Logic').item.json.scenes;
const projectId = $('Execute Logic').item.json.project_id;

// Detect fight scenes
const fightScenes = planningData.filter(p => p.fight_scene === true);

// Adjust emotional cinematography
const emotionalScenes = planningData.map(p => ({
  ...p,
  emotional_cinematography_adjusted: true,
  cinematography: {
    ...p.cinematography,
    emotional_adaptation: p.emotional_beats ? p.emotional_beats.map(eb => eb.moment).join(' -> ') : 'neutral'
  }
}));

// Calculate total durations
const totalDuration = emotionalScenes.reduce((sum, s) => sum + (s.duration_estimate || 30), 0);

// Update scenes with planning metadata
const sceneUpdates = emotionalScenes.map(p => {
  const scene = scenes.find(s => s.id === p.scene_id || s.scene_number === p.scene_number);
  return {
    json: {
      scene_id: p.scene_id || (scene ? scene.id : null),
      project_id: projectId,
      metadata: p
    }
  };
}).filter(s => s.json.scene_id);

return [{
  json: {
    project_id: projectId,
    scene_updates: sceneUpdates,
    total_scenes: scenes.length,
    fight_scenes: fightScenes.length,
    total_duration_seconds: totalDuration,
    total_duration_formatted: `${Math.floor(totalDuration/60)}m ${totalDuration%60}s`,
    average_duration: Math.round(totalDuration / scenes.length),
    planning_data: emotionalScenes
  }
}];

